#!/usr/bin/env python3
"""Execute production downloader/open/verify/coordinator methods with no network sockets.
The URL factory and package parser are explicit boundaries; filesystem, hashing,
policy, deadlines, redirects, attempt guards and promotion are production code.
"""
from pathlib import Path
import re,sys
source=Path(sys.argv[1]).read_text();modern='class DownloadAttempt' in source; manifestModern='private Candidate fetchManifest' in source

def blocks(pattern):
 out=[]
 for m in re.finditer(pattern,source,re.M):
  start=m.start();i=source.index('{',start);depth=0;quote=None;escape=False;comment=None
  while i<len(source):
   c=source[i];pair=source[i:i+2]
   if comment=='line':
    if c=='\n':comment=None
   elif comment=='block':
    if pair=='*/':comment=None;i+=1
   elif quote:
    if escape:escape=False
    elif c=='\\':escape=True
    elif c==quote:quote=None
   elif pair=='//':comment='line';i+=1
   elif pair=='/*':comment='block';i+=1
   elif c in ('"',"'"):quote=c
   elif c=='{':depth+=1
   elif c=='}':
    depth-=1
    if depth==0:out.append(source[start:i+1].replace('private ',''));break
   i+=1
 return out
names=['automaticChecksEnabled','check','fetchManifest','download','transfer','open','verify','signerHashes','hex','live','finish','failed','stateWasReady','userError','cancel','destroy']
if manifestModern:names+=['finishManifest','readManifest','nextManifestNonce']
if modern:names+=['finishDownload','remainingTimeout','disconnect','liveDownload','transferSource','interruptedDownload']
else:names+=['hashFile']
methods=[]
for name in names:
 found=blocks(r'^    (?:private )?(?:static )?(?:void|boolean|String|String\[\]|int|long|HttpURLConnection|DownloadAttempt|Candidate|byte\[\])\s+'+name+r'\([^;\n]*\)(?: throws [^\n{]+)?\s*\{')
 if not found:raise SystemExit('MISSING_ACTUAL_DOWNLOAD_METHOD '+name)
 methods+=found
